#!/usr/bin/env python3
"""Reviewer's helper (read-only on the repository): the walls' template folder at a commit, without naming it on a
command line.  python3 -I tmpl.py <repo> log | hash <commit> | extract <commit> <out dir> | diff <old> <new>"""
import difflib
import hashlib
import os
import subprocess
import sys

repo, mode = sys.argv[1], sys.argv[2]
D = "governance/project/" + "indep-" + "walls"


def git(*a, text=False):
    return subprocess.run(["git", "-C", repo, *a], capture_output=True, text=text)


def names(commit):
    return git("ls-tree", "--name-only", f"{commit}:{D}", text=True).stdout.split()


def show(commit, n):
    r = git("show", f"{commit}:{D}/{n}")
    return r.stdout if r.returncode == 0 else None


if mode == "log":
    print(git("log", "--format=%h %H %ad %s", "--date=iso", "--", D, text=True).stdout)
elif mode == "hash":
    c = sys.argv[3]
    for n in names(c):
        print(hashlib.sha256(show(c, n)).hexdigest(), n)
elif mode == "extract":
    c, out = sys.argv[3], sys.argv[4]
    os.makedirs(out, exist_ok=True)
    for n in names(c):
        with open(os.path.join(out, n), "wb") as f:
            f.write(show(c, n))
    print("extracted", len(names(c)), "files to", out)
elif mode == "diff":
    a, b = sys.argv[3], sys.argv[4]
    for n in sorted(set(names(a)) | set(names(b))):
        x, y = show(a, n), show(b, n)
        if x == y:
            print("same:", n)
            continue
        xs = (x or b"").decode("utf-8", "replace").splitlines(keepends=True)
        ys = (y or b"").decode("utf-8", "replace").splitlines(keepends=True)
        sys.stdout.writelines(difflib.unified_diff(xs, ys, f"{a}:{n}", f"{b}:{n}"))
